-- KO-225 group 5 continuation batch 12

update public.content_variants set body = $json${"text":"All of Bayu's friends bought GOTO shares because they went viral on TikTok. Bayu is afraid of missing out (FOMO) and wants to buy too, even though he doesn't know the company's fundamentals. At the same time, he is afraid of loss (loss aversion). These two biases clouded his judgment."}$json$::jsonb where id = '9dea08b5-ac2e-4be5-bea4-33be2dc5982b';
update public.content_variants set body = $json${"text":"A chicken noodle seller sets aside IDR 2,000,000 per month. He doesn't keep everything in one place, but rather 50% in BCA deposits, 30% in mutual funds, and 20% in blue chip shares. If one instrument goes down, the other one holds up.","source_ids":["47189cc8-8e51-4890-ace4-3f30b913f5ee"]}$json$::jsonb where id = '9f6e2fcf-672b-4b77-a697-ef21d002828d';
update public.content_variants set body = $json${"text":"Maya has a portfolio consisting of BBCA, BBRI, TLKM shares and money market mutual funds. When GOTO price fell 20% due to technology sector news, Maya's portfolio remained stable because it was only a small portion in that sector.","source_ids":["47189cc8-8e51-4890-ace4-3f30b913f5ee","c7c57d03-733f-4fe8-bd15-ce3a1cd4a760"]}$json$::jsonb where id = '9f73e989-324c-4c85-9697-dac18fd87529';
update public.content_variants set body = $json${"text":"Coins use paper trading with daily closing prices. In real time, share prices can vary slightly due to spreads and brokerage fees. Paper trading teaches the concept without real transaction costs.","source_ids":["52aff5b9-0d1c-42d8-8dba-a1a97a3f3b3f"]}$json$::jsonb where id = 'a0beb091-dc10-4345-a937-35390f897e1c';
update public.content_variants set body = $json${"text":"Open is the opening price, high/low is the highest/lowest price, close is the closing price, volume is the number of shares traded, and market cap is the company's market value."}$json$::jsonb where id = 'a2c8861f-f009-41b2-9453-691f5045c28e';
update public.content_variants set body = $json${"text":"Paying yourself first means setting aside money for savings or investments as soon as your income comes in, before paying other people or buying what you want."}$json$::jsonb where id = 'a42e5419-fed3-49f2-9a17-4a75b714a7d3';
update public.content_variants set body = $json${"text":"OJK supervises banks, insurance, mutual funds and capital markets in Indonesia. Legal financial products must have permission from the OJK."}$json$::jsonb where id = 'a43832d5-5f4c-470d-a9b5-7683ede38b43';
update public.content_variants set body = $json${"text":"Bayu was lent IDR 500,000 by his friend. He can ask to be paid today or in three months. If paid today, Bayu can buy the cellphone charger he needs now and start working as a freelancer. Money received early gives more options."}$json$::jsonb where id = 'a47fe829-db38-4187-b7fd-3b7a734a2635';
update public.content_variants set body = $json${"text":"Ani works part time with an income of IDR 2,500,000 per month. He applies the 50/30/20 rule: IDR 1,250,000 for needs (boarding, transport, food), IDR 750,000 for desires (streaming, hanging out), and IDR 500,000 for savings and paying off small debts to the family.","source_ids":["7f4b83f2-8f1d-415c-9d4f-64e6284bef04"]}$json$::jsonb where id = 'a48ffaed-298f-4de6-9697-7e8b4d8e689f';
update public.content_variants set body = $json${"text":"Dewi saves IDR 1,000,000 in an instrument that gives an average return of 8% per year. With compound interest, after 10 years the value will be around IDR 2,160,000. His friend keeps IDR 1,000,000 in cash, but his purchasing power has decreased due to inflation.","source_ids":["47189cc8-8e51-4890-ace4-3f30b913f5ee"]}$json$::jsonb where id = 'a4c1cb48-291b-48b3-a34d-acc9d9e157fa';

